<?php
if (!defined('ROUTER_LOADED')) { http_response_code(403); exit('Accès direct interdit.'); }
if (!userCan($user,'stock.reconciliation')) { http_response_code(403); echo '<div class="rounded-md border border-red-200 bg-red-50 p-4 text-red-700">Accès refusé.</div>'; return; }
require_once __DIR__.'/../../api/database.php'; require_once __DIR__.'/_inventory.php';
$db=Database::getInstance(); $errors=[]; $productId=(int)($_GET['product_id']??$_POST['product_id']??0); $newQuantity=(string)($_POST['new_quantity']??''); $reason=trim((string)($_POST['reason']??'')); inventoryEnsureCsrf();
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    if(!hash_equals($_SESSION['csrf_token'],(string)($_POST['csrf_token']??'')))$errors[]='Le formulaire a expiré. Rechargez puis réessayez.';
    if(!is_numeric($newQuantity)||!is_finite((float)$newQuantity)||(float)$newQuantity<0)$errors[]='La quantité comptée doit être positive ou nulle.';
    if($reason===''||mb_strlen($reason)>500)$errors[]='Le motif de la réconciliation est obligatoire.';
    if(!$errors){$pdo=$db->getPdo();try{$pdo->beginTransaction();$product=$db->query('SELECT * FROM stock WHERE id = ? FOR UPDATE',[$productId])->fetch();if(!$product||(int)$product['is_archived']===1)throw new RuntimeException('Produit introuvable ou archiv?.');$before=(float)$product['actual_quantity'];$after=round((float)$newQuantity,2);$difference=round($after-$before,2);if($difference==0)throw new RuntimeException('La quantité comptée est identique au stock actuel.');$status=$after<=0?'Rupture':'Disponible';$db->execute('UPDATE stock SET actual_quantity = ?, status = ? WHERE id = ?',[$after,$status,$productId]);$db->execute('INSERT INTO quantity_corrections (product_id, medicine_name, old_entry_quantity, new_entry_quantity, old_stock_quantity, new_stock_quantity, difference, reason, corrected_by, correction_date, correction_time) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, CURDATE(), CURTIME())',[(string)$productId,$product['medicine_name'],(float)$product['registered_quantity'],(float)$product['registered_quantity'],$before,$after,$difference,$reason,$user['nom_complet']]);inventoryLogMovement($db,$product,'correction',abs($difference),$before,$after,(float)$product['actual_price'],null,$reason,$user['nom_complet']);$pdo->commit();$_SESSION['flash_message']=['type'=>'success','text'=>'Inventaire corrigé pour « '.$product['medicine_name'].' » : '.number_format($before,2,',',' ').' → '.number_format($after,2,',',' ').'.'];header('Location: '.app_route_url('stock/reconciliation'));exit;}catch(Throwable $error){if($pdo->inTransaction())$pdo->rollBack();error_log('Stock reconciliation failed: '.$error->getMessage());$errors[]=$error instanceof RuntimeException?$error->getMessage():'La réconciliation a échoué.';}}
}
$products=$db->fetchAll('SELECT id,medicine_name,actual_quantity,seuil,sell_type FROM stock WHERE is_archived = 0 ORDER BY medicine_name');$flash=$_SESSION['flash_message']??null;unset($_SESSION['flash_message']);
?>
<section class="space-y-5"><header><p class="text-sm font-semibold text-blue-800">Inventaire</p><h1 class="mt-1 text-2xl font-bold text-slate-900">Réconciliation du stock</h1><p class="mt-1 text-sm text-slate-600">Comparez le stock système au comptage physique. Chaque écart est conservé dans l’historique.</p></header>
<?php if($flash):?><div role="status" class="rounded-md border border-green-200 bg-green-50 p-4 text-sm text-green-800"><?=inventoryEscape($flash['text']??'')?></div><?php endif;?>
<?php if($errors):?><div role="alert" class="rounded-md border border-red-200 bg-red-50 p-4 text-sm text-red-800"><ul class="list-disc pl-5"><?php foreach(array_unique($errors) as $error):?><li><?=inventoryEscape($error)?></li><?php endforeach;?></ul></div><?php endif;?>
<form method="post" class="grid gap-4 rounded-md border border-slate-200 bg-white p-5 md:grid-cols-[minmax(0,1.5fr)_12rem_minmax(0,1fr)_auto] md:items-end"><input type="hidden" name="csrf_token" value="<?=inventoryEscape($_SESSION['csrf_token'])?>"><label class="space-y-1 text-sm font-medium">Produit<select name="product_id" required class="w-full rounded-md border border-slate-300 bg-white px-3 py-2.5"><option value="">Choisir un produit</option><?php foreach($products as $product):?><option value="<?=(int)$product['id']?>" <?= $productId===(int)$product['id']?'selected':''?>><?=inventoryEscape($product['medicine_name'])?> · système <?=number_format((float)$product['actual_quantity'],2,',',' ')?> <?=inventoryEscape($product['sell_type'])?></option><?php endforeach;?></select></label><label class="space-y-1 text-sm font-medium">Quantité comptée<input name="new_quantity" type="number" min="0" step="0.01" required value="<?=inventoryEscape($newQuantity)?>" class="w-full rounded-md border border-slate-300 px-3 py-2.5 font-normal"></label><label class="space-y-1 text-sm font-medium">Motif<input name="reason" required maxlength="500" value="<?=inventoryEscape($reason)?>" placeholder="Inventaire physique…" class="w-full rounded-md border border-slate-300 px-3 py-2.5 font-normal"></label><button class="rounded-md bg-blue-800 px-4 py-2.5 text-sm font-semibold text-white">Enregistrer l’écart</button></form>
<div class="overflow-x-auto rounded-md border border-slate-200 bg-white"><table class="min-w-full divide-y text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th class="px-4 py-3">Produit</th><th class="px-4 py-3 text-right">Stock système</th><th class="px-4 py-3 text-right">Seuil</th><th class="px-4 py-3">Action</th></tr></thead><tbody class="divide-y divide-slate-100"><?php if(!$products):?><tr><td colspan="4" class="px-4 py-10 text-center text-slate-500">Aucun produit à réconcilier.</td></tr><?php else:foreach($products as $product):?><tr><td class="px-4 py-3 font-medium"><?=inventoryEscape($product['medicine_name'])?></td><td class="px-4 py-3 text-right"><?=number_format((float)$product['actual_quantity'],2,',',' ')?> <?=inventoryEscape($product['sell_type'])?></td><td class="px-4 py-3 text-right"><?=number_format((float)$product['seuil'],0,',',' ')?></td><td class="px-4 py-3"><a href="<?=inventoryEscape(app_route_url('stock/reconciliation'))?>?product_id=<?=(int)$product['id']?>" class="text-sm font-medium text-blue-800 hover:underline">Compter</a></td></tr><?php endforeach;endif;?></tbody></table></div></section>
